/** 模板中的单个 Agent 定义 */
export interface AgentTemplate {
    name: string;
    role: string;
    description: string;
    soul: string;
    initialSkills: string[];
    suggestedModel?: string;
    toolsMd?: string;
    heartbeatMd?: string;
    userMd?: string;
    bootstrapMd?: string;
    memoryMd?: string;
    skills?: Array<{
        id: string;
        name: string;
        summary: string;
        description: string;
        scenarios: string[];
        steps: string[];
        tags: string[];
        category: string;
        version: string;
        installCommand: string;
        securityScore?: number | null;
        sourceFramework?: string;
        isMarketplaceSkill?: boolean;
        license?: string;
        compatibility?: string[];
        metadata?: Record<string, string>;
        allowedTools?: string[];
        prerequisites: string[];
        failureModes: string[];
        sourceTier: string;
        dependsOn: string[];
        conflictsWith: string[];
        triggers: string[];
        strategicLink: string;
        geneSources?: Array<{
            kind: string;
            name: string;
            mapsTo: string;
        }>;
        approvalRequired?: string[];
    }>;
}
export interface TeamTemplate {
    id: string;
    name: string;
    description: string;
    version: string;
    agents: AgentTemplate[];
    agentsMd: string;
    firstTask: string;
    teamWorkflow: string;
    manifest?: Record<string, unknown>;
    display?: Record<string, unknown>;
    demoData?: Record<string, string>;
    icon?: string;
    tags?: string[];
    evolutionCount?: number;
    installCount?: number;
    protocol?: Record<string, unknown>;
}
